window.BOSS_KB_FILES = ["boss_kb.pl","boss_derive.pl","boss_rules.pl","boss_infer.pl","boss_advice.pl"];
window.BOSS_KB = {"boss_kb.pl":"% ============================================================\r\n% B0SS - Business Opportunity Screening System\r\n% boss_kb.pl - Fixed domain knowledge base\r\n%\r\n% 25 unconditional facts, transcribed verbatim from SRS section 5.\r\n% These never change between assessments. Session facts asserted\r\n% from the user's answers live in working memory, not here.\r\n%\r\n% Count: 7 supported_business + 3 safe_funding + 3 dangerous_funding\r\n%      + 4 demand_level + 4 cash_cycle_type + 4 legal_value = 25\r\n% ============================================================\r\n\r\n% --- Business types B0SS is allowed to screen (7) ---\r\nsupported_business(service).\r\nsupported_business(retail).\r\nsupported_business(online).\r\nsupported_business(education).\r\nsupported_business(professional_service).\r\nsupported_business(food).\r\nsupported_business(owner_trade).\r\n\r\n% --- Funding sources that do not endanger the household (3) ---\r\nsafe_funding(own_savings).\r\nsafe_funding(family_interest_free).\r\nsafe_funding(formal_affordable).\r\n\r\n% --- Funding sources that trigger the R10 absolute override (3) ---\r\ndangerous_funding(informal_high_interest).\r\ndangerous_funding(pawned_asset).\r\ndangerous_funding(home_secured_loan).\r\n\r\n% --- Strength of evidence that somebody will actually pay (4) ---\r\ndemand_level(none).\r\ndemand_level(anecdotal).\r\ndemand_level(observed).\r\ndemand_level(validated).\r\n\r\n% --- How money moves in and out of the business (4) ---\r\ncash_cycle_type(advance_payment).\r\ncash_cycle_type(on_delivery).\r\ncash_cycle_type(long_credit).\r\ncash_cycle_type(heavy_stock).\r\n\r\n% --- Licensing / legal position (4) ---\r\nlegal_value(none_required).\r\nlegal_value(routine).\r\nlegal_value(unknown).\r\nlegal_value(blocking).\r\n","boss_derive.pl":"% ============================================================\r\n% B0SS - boss_derive.pl\r\n% Working-memory declarations and derived values.\r\n%\r\n% SRS section 4.2: these are CALCULATED from user answers and are\r\n% never asked as separate questions.\r\n%\r\n% The clauses in this file are derivation parameters, NOT domain\r\n% facts: the 25 knowledge-base facts of SRS section 5 remain\r\n% exactly 25. See DECISIONS.md, decision 1.\r\n% ============================================================\r\n\r\n% --- Session facts, asserted by the interface (SRS 4.1) ---\r\n:- dynamic(business_type/1).\r\n:- dynamic(venture_type/1).\r\n:- dynamic(channel_type/1).\r\n:- dynamic(demand_evidence/1).\r\n:- dynamic(target_customer/1).\r\n:- dynamic(repeat_demand/1).\r\n:- dynamic(price_status/1).\r\n:- dynamic(owner_experience/1).\r\n:- dynamic(owner_time/1).\r\n:- dynamic(reversibility/1).\r\n:- dynamic(startup_cost/1).\r\n:- dynamic(monthly_cost/1).\r\n:- dynamic(capital_available/1).\r\n:- dynamic(capital_status/1).\r\n:- dynamic(funding_source/1).\r\n:- dynamic(stated_rate/1).\r\n:- dynamic(margin_rate/1).\r\n:- dynamic(breakeven_months/1).\r\n:- dynamic(personal_runway/1).\r\n:- dynamic(cash_cycle/1).\r\n:- dynamic(competition/1).\r\n:- dynamic(differentiation/1).\r\n:- dynamic(dependency/1).\r\n:- dynamic(legal_status/1).\r\n\r\n% ------------------------------------------------------------\r\n% SRS 4.2 - arithmetic\r\n% ------------------------------------------------------------\r\n\r\n% capital_requirement = startup_cost + (6 x monthly_operating_cost)\r\ncapital_requirement(C) :-\r\n    startup_cost(S),\r\n    monthly_cost(M),\r\n    C is S + 6 * M.\r\n\r\n% funded_months = max(0, capital_available - startup_cost) / monthly_cost\r\n% Written as a conditional rather than max/2: Tau-Prolog's evaluable\r\n% functor coverage is thinner than SWI's.\r\nfunded_months(F) :-\r\n    capital_available(A),\r\n    startup_cost(S),\r\n    monthly_cost(M),\r\n    M > 0,\r\n    Spare is A - S,\r\n    (   Spare > 0\r\n    ->  F is Spare / M\r\n    ;   F = 0\r\n    ).\r\n\r\n% survival_gap = funded_months - breakeven_months\r\nsurvival_gap(G) :-\r\n    funded_months(F),\r\n    breakeven_months(B),\r\n    G is F - B.\r\n\r\n% ------------------------------------------------------------\r\n% Margin: numeric input -> category (decision 1)\r\n% SRS 3.5 rule of thumb: above 30% retail, above 45% services.\r\n% ------------------------------------------------------------\r\n\r\nmargin_floor(retail, 30).\r\nmargin_floor(food, 30).\r\nmargin_floor(service, 45).\r\nmargin_floor(online, 45).\r\nmargin_floor(education, 45).\r\nmargin_floor(professional_service, 45).\r\nmargin_floor(owner_trade, 45).\r\n\r\nmargin_level(L) :-\r\n    margin_rate(R),\r\n    business_type(T),\r\n    margin_floor(T, Floor),\r\n    Strong is Floor + 15,\r\n    (   R >= Strong ->  L = strong\r\n    ;   R >= Floor  ->  L = adequate\r\n    ;                   L = low\r\n    ).\r\n\r\n% ------------------------------------------------------------\r\n% Cost of the money funding the business (needed by R11).\r\n% Own savings and interest-free family money cost nothing.\r\n% Any borrowed source uses the rate the user stated; if no rate\r\n% is known this simply fails, so R11 cannot fire on a guess\r\n% (NFR-Robustness: the system must not invent defaults).\r\n% ------------------------------------------------------------\r\n\r\nfree_capital(own_savings).\r\nfree_capital(family_interest_free).\r\n\r\neffective_funding_cost(0) :-\r\n    funding_source(S),\r\n    free_capital(S).\r\neffective_funding_cost(R) :-\r\n    funding_source(S),\r\n    \\+ free_capital(S),\r\n    stated_rate(R).\r\n\r\n% ------------------------------------------------------------\r\n% Domain validation and scope - what the type facts in boss_kb.pl\r\n% are for. Every categorical answer must be a value this knowledge\r\n% base recognises, and the business itself must be one B0SS is\r\n% allowed to screen (SRS section 2).\r\n% ------------------------------------------------------------\r\n\r\nknown_value(business_type(T))   :- supported_business(T).\r\nknown_value(demand_evidence(unknown)).\r\nknown_value(demand_evidence(D)) :- demand_level(D).\r\nknown_value(cash_cycle(C))      :- cash_cycle_type(C).\r\nknown_value(legal_status(L))    :- legal_value(L).\r\nknown_value(funding_source(F))  :- safe_funding(F).\r\nknown_value(funding_source(F))  :- dangerous_funding(F).\r\n\r\nchecked_input(demand_evidence(_)).\r\nchecked_input(cash_cycle(_)).\r\nchecked_input(legal_status(_)).\r\nchecked_input(funding_source(_)).\r\n\r\n% An answer this knowledge base does not recognise. The system must\r\n% not reason from a value it has no facts about.\r\nunrecognised(Name) :-\r\n    checked_input(Fact),\r\n    call(Fact),\r\n    \\+ known_value(Fact),\r\n    functor(Fact, Name, _).\r\n\r\n% SRS section 2: B0SS must not evaluate businesses outside the\r\n% supported list - pharmaceuticals, finance, franchises and the rest\r\n% need specialist judgement these rules do not contain.\r\nin_scope :-\r\n    business_type(T),\r\n    supported_business(T).\r\n\r\nout_of_scope(T) :-\r\n    business_type(T),\r\n    \\+ supported_business(T).\r\n\r\n% ------------------------------------------------------------\r\n% Critical unknowns - SRS 9.1 step 2 (decision 4)\r\n% Demand, price, capital and legal status are the four inputs\r\n% that block a positive answer when they are not known.\r\n% ------------------------------------------------------------\r\n\r\ncritical_unknown(demand) :-\r\n    demand_evidence(unknown).\r\ncritical_unknown(price) :-\r\n    price_status(P),\r\n    member(P, [assumed, unknown]).\r\ncritical_unknown(capital) :-\r\n    capital_status(unknown).\r\ncritical_unknown(legal) :-\r\n    legal_status(unknown).\r\n","boss_rules.pl":"% ============================================================\r\n% B0SS - boss_rules.pl\r\n% The 25 expert IF-THEN rules (SRS section 7).\r\n%\r\n% Representation is the one documented in SRS 7.1:\r\n%     rule(Id, Conclusion, CF) :- Evidence.\r\n%\r\n% Where the expert stated two outcomes for one rule (a conclusion\r\n% plus a validation_gap or red_flag entry) the conclusion is an\r\n% and/2 term. concludes/3 in boss_infer.pl unfolds it, so rule/3\r\n% keeps the arity and shape the SRS shows.\r\n%\r\n% CF expresses the expert's belief in the rule conclusion when its\r\n% evidence is present. It is NOT a probability of business success.\r\n% ============================================================\r\n\r\n% Dynamic only so the knowledge editor's checks (boss_kbcheck.pl) can\r\n% read rule bodies with clause/2: Tau-Prolog refuses clause/2 on\r\n% static code. Nothing asserts or retracts rules at run time.\r\n:- dynamic(rule/3).\r\n\r\n% ---------- Market attractiveness ----------\r\n\r\n% R01 - strongest practical evidence of a repeatable market.\r\nrule(r01, market_attractiveness(high), 0.8) :-\r\n    demand_evidence(validated),\r\n    repeat_demand(recurring).\r\n\r\n% R02 - real evidence plus a reachable customer group.\r\n% Concludes 'moderate': R01 already covers the 'high' case.\r\nrule(r02, market_attractiveness(moderate), 0.6) :-\r\n    demand_evidence(D),\r\n    member(D, [observed, validated]),\r\n    target_customer(specific).\r\n\r\n% R03 - interest or encouragement is not willingness to pay.\r\nrule(r03, and(market_attractiveness(low), validation_gap(test_demand)), -0.8) :-\r\n    demand_evidence(D),\r\n    member(D, [none, anecdotal]).\r\n\r\n% R04 - financial conclusions are weak until the price is checked.\r\nrule(r04, validation_gap(validate_price), -0.4) :-\r\n    price_status(assumed).\r\n\r\n% ---------- Competitive position ----------\r\n\r\n% R05 - a small entrant cannot rely on an undifferentiated price fight.\r\nrule(r05, competitive_position(weak), -0.8) :-\r\n    competition(many_strong),\r\n    differentiation(D),\r\n    member(D, [none, price_only]).\r\n\r\n% R06 - a specific reason to choose the business can offset crowding.\r\nrule(r06, competitive_position(strong), 0.6) :-\r\n    competition(C),\r\n    member(C, [few, many_weak]),\r\n    differentiation(strong).\r\n\r\n% ---------- Financial readiness ----------\r\n\r\n% R07 - funded through startup and six months from a safe source.\r\nrule(r07, financial_readiness(ready), 0.8) :-\r\n    capital_available(A),\r\n    capital_requirement(R),\r\n    A >= R,\r\n    funding_source(S),\r\n    safe_funding(S).\r\n\r\n% R08 - underfunded; the plan should be reduced or delayed.\r\n% Concludes 'marginal': R09 already covers the severe case.\r\nrule(r08, financial_readiness(marginal), -0.6) :-\r\n    capital_available(A),\r\n    capital_requirement(R),\r\n    Half is 0.5 * R,\r\n    A >= Half,\r\n    A < R.\r\n\r\n% R09 - unlikely to stay open long enough to test the market.\r\nrule(r09, and(overall_risk(high), red_flag(severe_underfunding)), -0.8) :-\r\n    capital_available(A),\r\n    capital_requirement(R),\r\n    Half is 0.5 * R,\r\n    A < Half.\r\n\r\n% ---------- Absolute overrides ----------\r\n\r\n% R10 - risky funding can endanger the household.\r\nrule(r10, recommendation(not_recommended), -1.0) :-\r\n    funding_source(S),\r\n    dangerous_funding(S).\r\n\r\n% R11 - each sale destroys value at the financing cost.\r\nrule(r11, recommendation(not_recommended), -1.0) :-\r\n    margin_rate(M),\r\n    effective_funding_cost(C),\r\n    M < C.\r\n\r\n% ---------- Margin, cash cycle and survival ----------\r\n\r\n% R12 - healthy margin and early cash collection make mistakes survivable.\r\nrule(r12, financial_readiness(ready), 0.6) :-\r\n    margin_level(L),\r\n    member(L, [adequate, strong]),\r\n    cash_cycle(C),\r\n    member(C, [advance_payment, on_delivery]).\r\n\r\n% R13 - money is tied up before cash returns to the business.\r\nrule(r13, overall_risk(high), -0.6) :-\r\n    cash_cycle(C),\r\n    member(C, [long_credit, heavy_stock]),\r\n    \\+ holds_upto(1, financial_readiness(ready)).\r\n\r\n% R14 - expected to run out of funded time before break-even.\r\nrule(r14, and(overall_risk(high), survival_runway(insufficient)), -0.8) :-\r\n    breakeven_months(B),\r\n    funded_months(F),\r\n    B > F.\r\n\r\n% ---------- Owner readiness ----------\r\n\r\n% R15 - hands-on experience reduces operating and quality-control errors.\r\nrule(r15, owner_readiness(strong), 0.8) :-\r\n    owner_experience(direct).\r\n\r\n% R16 - learning is expensive when the commitment cannot be reversed.\r\nrule(r16, owner_readiness(weak), -0.8) :-\r\n    owner_experience(none),\r\n    reversibility(low).\r\n\r\n% R17 - low-cost reversible starts allow the owner to learn safely.\r\nrule(r17, owner_readiness(adequate), 0.4) :-\r\n    owner_experience(none),\r\n    reversibility(high).\r\n\r\n% ---------- Operations ----------\r\n\r\n% R18 - a walk-in business must be available during customer hours.\r\nrule(r18, operational_readiness(not_ready), -0.6) :-\r\n    owner_time(insufficient),\r\n    channel_type(walk_in).\r\n\r\n% R19 - one customer, supplier, person or platform is a single point of failure.\r\nrule(r19, and(overall_risk(high), red_flag(concentration)), -0.6) :-\r\n    dependency(high).\r\n\r\n% R20 - household pressure forces damaging short-term business decisions.\r\nrule(r20, and(overall_risk(high), red_flag(household_exposure)), -0.8) :-\r\n    personal_runway(P),\r\n    P < 3,\r\n    breakeven_months(B),\r\n    B > 6.\r\n\r\n% R21 - the business cannot legally operate in the proposed form.\r\nrule(r21, recommendation(not_recommended), -1.0) :-\r\n    legal_status(blocking).\r\n\r\n% ---------- Final recommendation rules ----------\r\n\r\n% R22 - report insufficient basis rather than guess.\r\n% \\+ \\+ gives exactly one solution however many unknowns exist.\r\nrule(r22, recommendation(further_validation_required), 0.0) :-\r\n    \\+ \\+ critical_unknown(_).\r\n\r\n% R23 - nothing in the screening currently argues against detailed planning.\r\nrule(r23, recommendation(proceed), 0.8) :-\r\n    \\+ absolute_override,\r\n    \\+ critical_unknown(_),\r\n    core_positive,\r\n    holds(financial_readiness(ready)),\r\n    holds(owner_readiness(O)),\r\n    member(O, [adequate, strong]),\r\n    \\+ weakness(_).\r\n\r\n% R24 - the opportunity may continue only with stated mitigations.\r\nrule(r24, recommendation(proceed_with_caution), 0.6) :-\r\n    \\+ absolute_override,\r\n    \\+ critical_unknown(_),\r\n    core_positive,\r\n    weakness_count(N),\r\n    N > 0,\r\n    N =< 2.\r\n\r\n% R25 - the current scale/model should change before reassessment.\r\nrule(r25, recommendation(not_recommended_in_this_form), -0.8) :-\r\n    \\+ absolute_override,\r\n    \\+ critical_unknown(_),\r\n    severe_risk_count(N),\r\n    N >= 2.\r\n","boss_infer.pl":"% ============================================================\r\n% B0SS - boss_infer.pl\r\n% Inference control: rule stratification, severity tables and the\r\n% SRS section 9.1 priority ladder.\r\n%\r\n% Backward chaining is the query strategy (SRS section 4). Rules\r\n% are grouped into levels so that a rule which asks what another\r\n% rule concluded can never re-enter its own body:\r\n%\r\n%   level 1  intermediate conclusions drawn straight from facts\r\n%   level 2  intermediate conclusions that consult level 1 (R13)\r\n%   level 3  recommendation rules (overrides and final verdicts)\r\n%\r\n% holds/1 exposes levels 1-2 only, so the final rules can read the\r\n% intermediate picture while remaining outside it.\r\n% ============================================================\r\n\r\nrule_level(r01, 1). rule_level(r02, 1). rule_level(r03, 1).\r\nrule_level(r04, 1). rule_level(r05, 1). rule_level(r06, 1).\r\nrule_level(r07, 1). rule_level(r08, 1). rule_level(r09, 1).\r\nrule_level(r12, 1). rule_level(r14, 1). rule_level(r15, 1).\r\nrule_level(r16, 1). rule_level(r17, 1). rule_level(r18, 1).\r\nrule_level(r19, 1). rule_level(r20, 1).\r\nrule_level(r13, 2).\r\nrule_level(r10, 3). rule_level(r11, 3). rule_level(r21, 3).\r\nrule_level(r22, 3). rule_level(r23, 3). rule_level(r24, 3).\r\nrule_level(r25, 3).\r\n\r\n% Unfold an and/2 conclusion into its individual conclusions.\r\nunfold(and(A, B), C) :- !, ( unfold(A, C) ; unfold(B, C) ).\r\nunfold(C, C).\r\n\r\n% A rule fires when its body succeeds. Id is always bound before\r\n% rule/3 is called, so only that one clause is ever executed.\r\n%\r\n% The \\+ \\+ gives exactly one solution per rule. Without it a rule whose\r\n% body consults holds/1 succeeds once per rule that supports the same\r\n% conclusion - R23 yields two identical solutions when both R07 and R12\r\n% conclude financial_readiness(ready).\r\nfires(Id) :-\r\n    rule_level(Id, _),\r\n    \\+ \\+ rule(Id, _, _).\r\n\r\n% What an applicable rule up to level L concludes.\r\nholds_upto(L, C) :-\r\n    rule_level(Id, RL),\r\n    RL =< L,\r\n    rule(Id, Concl, _),\r\n    unfold(Concl, C).\r\n\r\n% Intermediate conclusions visible to the final recommendation rules.\r\nholds(C) :- holds_upto(2, C).\r\n\r\n% ------------------------------------------------------------\r\n% Severity tables (decision 3)\r\n% These make the SRS's prose thresholds - \"at most two manageable\r\n% weaknesses\", \"two or more severe unmitigated risks\" - countable,\r\n% and keep them editable in one place.\r\n% ------------------------------------------------------------\r\n\r\nsevere_risk(no_market)           :- holds(market_attractiveness(low)).\r\nsevere_risk(owner_unready)       :- holds(owner_readiness(weak)).\r\nsevere_risk(competitive_weak)    :- holds(competitive_position(weak)).\r\nsevere_risk(severe_underfunding) :- holds(red_flag(severe_underfunding)).\r\nsevere_risk(concentration)       :- holds(red_flag(concentration)).\r\nsevere_risk(household_exposure)  :- holds(red_flag(household_exposure)).\r\nsevere_risk(survival_runway)     :- holds(survival_runway(insufficient)).\r\n\r\nweakness(W) :- severe_risk(W).\r\nweakness(financial_marginal)     :- holds(financial_readiness(marginal)).\r\nweakness(operations_not_ready)   :- holds(operational_readiness(not_ready)).\r\nweakness(cash_cycle_slow) :-\r\n    holds(overall_risk(high)),\r\n    cash_cycle(C),\r\n    member(C, [long_credit, heavy_stock]).\r\n\r\nsevere_risk_count(N) :-\r\n    findall(R, severe_risk(R), L0),\r\n    sort(L0, L),\r\n    length(L, N).\r\n\r\nweakness_count(N) :-\r\n    findall(W, weakness(W), L0),\r\n    sort(L0, L),\r\n    length(L, N).\r\n\r\n% The core case the expert checks before any softer factor.\r\ncore_positive :-\r\n    \\+ \\+ ( holds(market_attractiveness(M)), member(M, [high, moderate]) ),\r\n    \\+ holds(owner_readiness(weak)),\r\n    \\+ holds(red_flag(severe_underfunding)).\r\n\r\n% ------------------------------------------------------------\r\n% Absolute overrides - SRS 8.1: R10, R11 and R21 bypass all\r\n% positive evidence.\r\n% ------------------------------------------------------------\r\n\r\nabsolute_override :-\r\n    member(Id, [r10, r11, r21]),\r\n    rule(Id, _, _),\r\n    !.\r\n\r\n% ------------------------------------------------------------\r\n% SRS 9.1 priority order\r\n% The verdict carries the CF of the rule that decided it (SRS 8.1:\r\n% \"the final recommendation rule has its own CF\"), so a CF edited in\r\n% boss_rules.pl is the CF the user sees. Only the two exits no rule\r\n% covers - out of scope and the fall-through - state 0.0 here.\r\n% ------------------------------------------------------------\r\n\r\nrecommendation(Rec, CF) :-\r\n    (   out_of_scope(_)\r\n    ->  Rec = out_of_scope,                  CF = 0.0\r\n    ;   absolute_override\r\n    ->  Rec = not_recommended,               override_cf(CF)\r\n    ;   critical_unknown(_)\r\n    ->  Rec = further_validation_required,   rule_cf(r22, CF)\r\n    ;   fires(r23)\r\n    ->  Rec = proceed,                       rule_cf(r23, CF)\r\n    ;   fires(r24)\r\n    ->  Rec = proceed_with_caution,          rule_cf(r24, CF)\r\n    ;   fires(r25)\r\n    ->  Rec = not_recommended_in_this_form,  rule_cf(r25, CF)\r\n    ;   Rec = further_validation_required,   CF = 0.0\r\n    ).\r\n\r\nrule_cf(Id, CF) :-\r\n    once(rule(Id, _, CF)).\r\n\r\n% Several overrides may fire; the strongest (most negative) decides.\r\noverride_cf(CF) :-\r\n    findall(C, ( override_fired(Id), rule_cf(Id, C) ), Cs),\r\n    sort(Cs, [CF|_]).\r\n\r\n% ------------------------------------------------------------\r\n% The path through the SRS 9.1 ladder that produced this answer.\r\n% Returned as a list of d(Gate, pass|exit, Detail) so the interface can\r\n% draw the route actually taken. This is derived from the same checks\r\n% recommendation/2 makes - it is not a hand-drawn picture of them.\r\n% ------------------------------------------------------------\r\n\r\noverride_fired(Id) :-\r\n    member(Id, [r10, r11, r21]),\r\n    rule(Id, _, _).\r\n\r\ndecision_path(P) :-\r\n    (   out_of_scope(T)\r\n    ->  P = [d(scope, exit, T)]\r\n    ;   S = d(scope, pass, ok),\r\n        (   absolute_override\r\n        ->  findall(I, override_fired(I), Os),\r\n            P = [S, d(override, exit, Os)]\r\n        ;   O = d(override, pass, []),\r\n            (   critical_unknown(_)\r\n            ->  findall(U, critical_unknown(U), Us0), sort(Us0, Us),\r\n                P = [S, O, d(unknowns, exit, Us)]\r\n            ;   U = d(unknowns, pass, []),\r\n                weakness_count(W),\r\n                severe_risk_count(V),\r\n                (   fires(r23)\r\n                ->  P = [S, O, U, d(proceed, exit, W)]\r\n                ;   Pr = d(proceed, pass, W),\r\n                    (   fires(r24)\r\n                    ->  P = [S, O, U, Pr, d(caution, exit, W)]\r\n                    ;   C = d(caution, pass, W),\r\n                        (   fires(r25)\r\n                        ->  P = [S, O, U, Pr, C, d(in_this_form, exit, V)]\r\n                        ;   P = [S, O, U, Pr, C, d(in_this_form, pass, V),\r\n                                 d(insufficient, exit, 0)]\r\n                        )\r\n                    )\r\n                )\r\n            )\r\n        )\r\n    ).\r\n\r\n% ------------------------------------------------------------\r\n% Explanation support - SRS section 10 / FR-08 / FR-09\r\n% ------------------------------------------------------------\r\n\r\n% Every rule that fired, with its conclusion and CF, strongest first.\r\ntrace(Trace) :-\r\n    findall(t(Abs, Id, Concl, CF),\r\n            ( fires(Id), rule(Id, Concl, CF), Abs is -abs(CF) ),\r\n            L0),\r\n    sort(L0, L1),\r\n    findall(fired(Id, Concl, CF), member(t(_, Id, Concl, CF), L1), Trace).\r\n\r\npositives(Top) :-\r\n    trace(T),\r\n    findall(fired(Id, C, CF), ( member(fired(Id, C, CF), T), CF > 0 ), L),\r\n    first_n(3, L, Top).\r\n\r\nconcerns(Top) :-\r\n    trace(T),\r\n    findall(fired(Id, C, CF), ( member(fired(Id, C, CF), T), CF < 0 ), L),\r\n    first_n(3, L, Top).\r\n\r\nmissing(M) :-\r\n    findall(U, critical_unknown(U), L0),\r\n    sort(L0, M).\r\n\r\ngaps(G) :-\r\n    findall(Item, holds(validation_gap(Item)), L0),\r\n    sort(L0, G).\r\n\r\nfirst_n(0, _, []) :- !.\r\nfirst_n(_, [], []) :- !.\r\nfirst_n(N, [H|T], [H|R]) :- N1 is N - 1, first_n(N1, T, R).\r\n\r\n% ------------------------------------------------------------\r\n% Single entry point queried by the interface.\r\n% ------------------------------------------------------------\r\n\r\nassess(assessment(Rec, CF, Pos, Con, Missing, Gaps, Trace, Money, Scope, Concl, Path)) :-\r\n    scope(Scope),\r\n    conclusions(Concl),\r\n    decision_path(Path),\r\n    recommendation(Rec, CF),\r\n    positives(Pos),\r\n    concerns(Con),\r\n    missing(Missing),\r\n    gaps(Gaps),\r\n    trace(Trace),\r\n    money(Money).\r\n\r\n% The six intermediate conclusions of SRS section 6, for the summary\r\n% panel. Each is whatever the applicable rules concluded.\r\nconclusion(market,     V) :- holds(market_attractiveness(V)).\r\nconclusion(competition,V) :- holds(competitive_position(V)).\r\nconclusion(finance,    V) :- holds(financial_readiness(V)).\r\nconclusion(owner,      V) :- holds(owner_readiness(V)).\r\nconclusion(operations, V) :- holds(operational_readiness(V)).\r\nconclusion(risk,       V) :- holds(overall_risk(V)).\r\n\r\nconclusions(L) :-\r\n    findall(c(K, V), conclusion(K, V), L0),\r\n    sort(L0, L).\r\n\r\n% Scope and input validation (SRS section 2).\r\nscope(scope(State, Bad)) :-\r\n    ( out_of_scope(T) -> State = out_of_scope(T)\r\n    ; in_scope        -> State = ok\r\n    ;                    State = ok\r\n    ),\r\n    findall(N, unrecognised(N), Bad0),\r\n    sort(Bad0, Bad).\r\n\r\n% Visible arithmetic for the explanation (SRS section 10).\r\nmoney(money(Req, Funded, Gap)) :-\r\n    ( capital_requirement(R) -> Req = R ; Req = unknown ),\r\n    ( funded_months(F)       -> Funded = F ; Funded = unknown ),\r\n    ( survival_gap(G)        -> Gap = G ; Gap = unknown ).\r\n","boss_advice.pl":"% ============================================================\r\n% B0SS - boss_advice.pl\r\n% Presentation knowledge: what each rule means in plain business\r\n% language, and the specific next action for every concern\r\n% (SRS section 10). Kept in the knowledge base rather than the\r\n% interface so it can be edited without touching the UI (FR-11).\r\n% ============================================================\r\n\r\n% ---------- Plain-language reading of each rule ----------\r\n\r\nrule_text(r01, 'Repeat customers already pay your price.').\r\nrule_text(r02, 'Observed demand, and you know the customer.').\r\nrule_text(r03, 'Nobody has paid yet; interest is not demand.').\r\nrule_text(r04, 'Your price is untested against the market.').\r\nrule_text(r05, 'Strong competitors, nothing that sets you apart.').\r\nrule_text(r06, 'A clear edge offsets the competition.').\r\nrule_text(r07, 'Capital covers startup plus 6 months, from a safe source.').\r\nrule_text(r08, 'You have most of the money, not all of it.').\r\nrule_text(r09, 'You have under half the money needed.').\r\nrule_text(r10, 'The funding could take the household down with it.').\r\nrule_text(r11, 'Margin is below the cost of the funding.').\r\nrule_text(r12, 'Healthy margin and early cash.').\r\nrule_text(r13, 'Cash goes out well before it comes in.').\r\nrule_text(r14, 'Funded months run out before break-even.').\r\nrule_text(r15, 'You have done this work yourself.').\r\nrule_text(r16, 'No hands-on experience, no cheap way to stop.').\r\nrule_text(r17, 'No experience, but a small, reversible start.').\r\nrule_text(r18, 'A walk-in business needs you there in customer hours.').\r\nrule_text(r19, 'One customer, supplier, person or platform can end it.').\r\nrule_text(r20, 'The household runs out of money before the business pays.').\r\nrule_text(r21, 'It cannot legally operate in this form.').\r\nrule_text(r22, 'Something critical is unknown, so no positive answer.').\r\nrule_text(r23, 'Nothing argues against detailed planning.').\r\nrule_text(r24, 'The core case holds; weaknesses need mitigation.').\r\nrule_text(r25, 'Several serious but fixable problems.').\r\n\r\n% ---------- A specific next action for every concern ----------\r\n\r\nnext_action(r03, 'Get one real payment or signed commitment at your price.').\r\nnext_action(r04, 'Ask 3 likely customers what they pay; check 2 competitors'' prices.').\r\nnext_action(r05, 'Name the one reason a customer would switch to you, or change the offer.').\r\nnext_action(r08, 'Raise the shortfall first, or cut the plan to fit your capital.').\r\nnext_action(r09, 'Redesign to a version you can fund for six months.').\r\nnext_action(r10, 'Change the funding or scale: no home-secured or high-interest money.').\r\nnext_action(r11, 'Recheck margin and interest; if the margin is real, each sale loses money.').\r\nnext_action(r13, 'Negotiate deposits or faster payment before buying stock.').\r\nnext_action(r14, 'Cut monthly costs or raise capital until funded months beat break-even.').\r\nnext_action(r16, 'Work in the trade for a season, or bring in an experienced partner.').\r\nnext_action(r18, 'Arrange cover for customer hours, or change channel.').\r\nnext_action(r19, 'Get the dependency in writing and line up a second option.').\r\nnext_action(r20, 'Keep 3 months of household costs outside the business, or delay.').\r\nnext_action(r21, 'Confirm the licence position with the authority first.').\r\n\r\n% ---------- Missing information -> what to go and find out ----------\r\n\r\nunknown_label(demand,  'Whether anyone will pay is untested.').\r\nunknown_label(price,   'The selling price is unvalidated.').\r\nunknown_label(capital, 'Your actual capital is not known.').\r\nunknown_label(legal,   'The licensing position is unknown.').\r\n\r\nunknown_action(demand,  'Take one deposit, pre-order or paid trial.').\r\nunknown_action(price,   'Check the price against real competitors and customers.').\r\nunknown_action(capital, 'Work out startup and monthly running costs.').\r\nunknown_action(legal,   'Find out which licences are needed, and if you can get them.').\r\n\r\n% SRS section 6 \"validation gap\": critical items that are assumed rather\r\n% than known. These are the heart of what B0SS is for.\r\ngap_label(test_demand,    'Demand is untested with money.').\r\ngap_label(validate_price, 'The selling price is unvalidated.').\r\n\r\ngap_action(test_demand,    'Take one deposit, pre-order or paid trial.').\r\ngap_action(validate_price, 'Check the price against 2 competitors and 3 likely customers.').\r\n\r\n% ---------- CF labels, SRS section 8 ----------\r\n\r\ncf_label(CF, 'Definitely not')    :- CF =< -0.9.\r\ncf_label(CF, 'Almost certainly not') :- CF > -0.9, CF =< -0.7.\r\ncf_label(CF, 'Probably not')      :- CF > -0.7, CF =< -0.5.\r\ncf_label(CF, 'Maybe not')         :- CF > -0.5, CF =< -0.3.\r\ncf_label(CF, 'Unknown / insufficient basis') :- CF > -0.3, CF < 0.3.\r\ncf_label(CF, 'Maybe')             :- CF >= 0.3, CF < 0.5.\r\ncf_label(CF, 'Probably')          :- CF >= 0.5, CF < 0.7.\r\ncf_label(CF, 'Almost certainly')  :- CF >= 0.7, CF < 0.9.\r\ncf_label(CF, 'Definitely')        :- CF >= 0.9.\r\n\r\n% ---------- The six intermediate conclusions (SRS section 6) ----------\r\n\r\nconclusion_label(market,     'Demand').\r\nconclusion_label(competition,'Competition').\r\nconclusion_label(finance,    'Money').\r\nconclusion_label(owner,      'Owner').\r\nconclusion_label(operations, 'Operations').\r\nconclusion_label(risk,       'Risk').\r\n\r\nconclusion_word(market, high,     'Strong').\r\nconclusion_word(market, moderate, 'Moderate').\r\nconclusion_word(market, low,      'No evidence').\r\nconclusion_word(competition, strong,   'Defensible').\r\nconclusion_word(competition, adequate, 'Adequate').\r\nconclusion_word(competition, weak,     'Exposed').\r\nconclusion_word(finance, ready,     'Funded').\r\nconclusion_word(finance, marginal,  'Short').\r\nconclusion_word(finance, not_ready, 'Not funded').\r\nconclusion_word(owner, strong,   'Experienced').\r\nconclusion_word(owner, adequate, 'Learnable').\r\nconclusion_word(owner, weak,     'Unready').\r\nconclusion_word(operations, ready,     'Workable').\r\nconclusion_word(operations, marginal,  'Tight').\r\nconclusion_word(operations, not_ready, 'Not workable').\r\nconclusion_word(risk, low,      'Low').\r\nconclusion_word(risk, moderate, 'Moderate').\r\nconclusion_word(risk, high,     'High').\r\nconclusion_word(risk, critical, 'Critical').\r\n\r\n% Whether a conclusion reads as positive, mixed or negative. Depends on\r\n% the dimension: 'high' is good for demand and bad for risk.\r\nconclusion_tone(market, high, good).      conclusion_tone(market, moderate, warn).\r\nconclusion_tone(market, low, bad).\r\nconclusion_tone(competition, strong, good). conclusion_tone(competition, adequate, warn).\r\nconclusion_tone(competition, weak, bad).\r\nconclusion_tone(finance, ready, good).    conclusion_tone(finance, marginal, warn).\r\nconclusion_tone(finance, not_ready, bad).\r\nconclusion_tone(owner, strong, good).     conclusion_tone(owner, adequate, warn).\r\nconclusion_tone(owner, weak, bad).\r\nconclusion_tone(operations, ready, good). conclusion_tone(operations, marginal, warn).\r\nconclusion_tone(operations, not_ready, bad).\r\nconclusion_tone(risk, low, good).         conclusion_tone(risk, moderate, warn).\r\nconclusion_tone(risk, high, bad).         conclusion_tone(risk, critical, bad).\r\n\r\n% ---------- The SRS 9.1 decision ladder, in plain words ----------\r\n\r\ngate_label(scope,        'Can B0SS screen it?').\r\ngate_label(override,     'Any deal-breaker?').\r\ngate_label(unknowns,     'Anything critical unknown?').\r\ngate_label(proceed,      'Core case clean?').\r\ngate_label(caution,      'Sound, with fixable weaknesses?').\r\ngate_label(in_this_form, '2+ serious risks?').\r\ngate_label(insufficient, 'Not enough to decide.').\r\n\r\ngate_detail(override,     'Dangerous funding, margin below funding cost, or a legal blocker.').\r\ngate_detail(unknowns,     'Demand, price, capital or licensing.').\r\ngate_detail(proceed,      'Demand, money, owner and operations all hold, with no weakness.').\r\ngate_detail(caution,      'Core factors positive and at most two weaknesses.').\r\ngate_detail(in_this_form, 'Serious but correctable - the plan should change first.').\r\n\r\ngate_outcome(scope,        out_of_scope).\r\ngate_outcome(override,     not_recommended).\r\ngate_outcome(unknowns,     further_validation_required).\r\ngate_outcome(proceed,      proceed).\r\ngate_outcome(caution,      proceed_with_caution).\r\ngate_outcome(in_this_form, not_recommended_in_this_form).\r\ngate_outcome(insufficient, further_validation_required).\r\n\r\n% ---------- Verdict headline text ----------\r\n\r\nverdict_text(out_of_scope, 'OUTSIDE WHAT B0SS CAN SCREEN').\r\nverdict_text(proceed, 'PROCEED').\r\nverdict_text(proceed_with_caution, 'PROCEED WITH CAUTION').\r\nverdict_text(further_validation_required, 'FURTHER VALIDATION REQUIRED').\r\nverdict_text(not_recommended, 'NOT RECOMMENDED').\r\nverdict_text(not_recommended_in_this_form, 'NOT RECOMMENDED IN THIS FORM').\r\n\r\nverdict_blurb(out_of_scope, 'This type needs specialist judgement these rules do not contain.').\r\nverdict_blurb(proceed, 'Continue to detailed planning. This is not a prediction of success.').\r\nverdict_blurb(proceed_with_caution, 'The core case is positive, but fix the concerns below before or during launch.').\r\nverdict_blurb(further_validation_required, 'Something critical is unknown. Check it before deciding.').\r\nverdict_blurb(not_recommended, 'A blocking condition makes this unacceptable, whatever else is strong.').\r\nverdict_blurb(not_recommended_in_this_form, 'Change the scale, model, dependency or timing, then assess again.').\r\n","boss_kbcheck.pl":"% ============================================================\r\n% B0SS - boss_kbcheck.pl\r\n% Knowledge-base verification, used by the knowledge editor.\r\n%\r\n% A meta-level program: it reads the rules as data through\r\n% clause/2 and reports anything that would make the knowledge\r\n% base inconsistent, incomplete or silently inert. It is not part\r\n% of the inference the user sees, and the assessment page never\r\n% loads it.\r\n%\r\n%   kb_issues(L)   L = sorted list of i(Severity, Code, Subject)\r\n%                  Severity is error (the editor refuses to save)\r\n%                  or warning (saved, but shown to the expert).\r\n%\r\n% The interface may assert ui_value(Attribute, Value) for every\r\n% value the questionnaire can produce (web/schema.js). Values\r\n% the knowledge base itself enumerates come from known_value/1.\r\n% ============================================================\r\n\r\n:- dynamic(ui_value/2).\r\n:- discontiguous(kb_issue/3).\r\n\r\nkb_issues(L) :-\r\n    findall(i(S, C, X), kb_issue(S, C, X), L0),\r\n    sort(L0, L).\r\n\r\n% ------------------------------------------------------------\r\n% Reading the rule base as data\r\n% ------------------------------------------------------------\r\n\r\nrule_clause(Id, Concl, CF, Body) :-\r\n    clause(rule(Id, Concl, CF), Body).\r\n\r\nrule_id(Id) :- rule_clause(Id, _, _, _).\r\n\r\n% Every simple goal in a rule body. Negation is kept, so a value\r\n% tested under \\+ is still checked against its domain.\r\nbody_goal(G, _) :- var(G), !, fail.\r\nbody_goal((A, B), G)    :- !, ( body_goal(A, G) ; body_goal(B, G) ).\r\nbody_goal((A ; B), G)   :- !, ( body_goal(A, G) ; body_goal(B, G) ).\r\nbody_goal((A -> B), G)  :- !, ( body_goal(A, G) ; body_goal(B, G) ).\r\nbody_goal(\\+ A, G)      :- !, body_goal(A, G).\r\nbody_goal(call(A), G)   :- !, body_goal(A, G).\r\nbody_goal(G, G).\r\n\r\n% Goals a rule may call that are not defined in the knowledge base.\r\nbuiltin(member/2).  builtin(memberchk/2). builtin(is/2).\r\nbuiltin((<)/2).     builtin((>)/2).       builtin((=<)/2).\r\nbuiltin((>=)/2).    builtin((=:=)/2).     builtin((=\\=)/2).\r\nbuiltin((=)/2).     builtin((\\=)/2).      builtin((==)/2).\r\nbuiltin((\\==)/2).   builtin(true/0).      builtin(fail/0).\r\nbuiltin(length/2).  builtin(findall/3).   builtin(sort/2).\r\nbuiltin(between/3). builtin(number/1).    builtin(atom/1).\r\n\r\n% A session attribute is one the interface asserts: boss_derive.pl\r\n% declares each of them dynamic (SRS 4.1).\r\nsession_attribute(A) :-\r\n    atom(A),\r\n    A \\== rule,\r\n    A \\== ui_value,\r\n    functor(H, A, 1),\r\n    predicate_property(H, dynamic).\r\n\r\n% The values an attribute is allowed to take, where anything says.\r\nhas_domain(A) :- T =.. [A, _], \\+ \\+ known_value(T), !.\r\nhas_domain(A) :- \\+ \\+ ui_value(A, _).\r\n\r\nknown_attr_value(A, V) :- T =.. [A, V], known_value(T), !.\r\nknown_attr_value(A, V) :- ui_value(A, V), !.\r\nknown_attr_value(A, unknown) :- ui_value(A, _), !.   % the \"I don't know\" answer\r\n\r\n% The categorical values a rule body tests an attribute against:\r\n% either attr(const), or attr(X) followed by member(X, [...]).\r\nconstraint(Body, A, [V]) :-\r\n    body_goal(Body, G),\r\n    G =.. [A, V],\r\n    atom(V),\r\n    session_attribute(A).\r\nconstraint(Body, A, Vs) :-\r\n    body_goal(Body, G),\r\n    G =.. [A, X],\r\n    var(X),\r\n    session_attribute(A),\r\n    body_goal(Body, member(Y, Vs)),\r\n    Y == X,\r\n    is_list(Vs).\r\n\r\ntested_value(Body, A, V) :-\r\n    constraint(Body, A, Vs),\r\n    member(V, Vs).\r\n\r\n% What a rule concludes, one term at a time (unfold/2: boss_infer.pl).\r\nconcludes_term(Id, C) :-\r\n    rule_clause(Id, Concl, _, _),\r\n    unfold(Concl, C).\r\n\r\n% ------------------------------------------------------------\r\n% 1. Certainty factors and identity\r\n% ------------------------------------------------------------\r\n\r\nkb_issue(error, cf_not_number, Id) :-\r\n    rule_clause(Id, _, CF, _),\r\n    \\+ number(CF).\r\nkb_issue(error, cf_out_of_range, Id-CF) :-\r\n    rule_clause(Id, _, CF, _),\r\n    number(CF),\r\n    ( CF < -1 ; CF > 1 ).\r\nkb_issue(error, id_not_atom, Id) :-\r\n    rule_clause(Id, _, _, _),\r\n    \\+ atom(Id).\r\nkb_issue(error, duplicate_id, Id) :-\r\n    rule_id(Id),\r\n    findall(x, rule_clause(Id, _, _, _), Xs),\r\n    length(Xs, N),\r\n    N > 1.\r\n\r\n% ------------------------------------------------------------\r\n% 2. Completeness: every rule wired into inference and explanation\r\n% ------------------------------------------------------------\r\n\r\n% Without a level, fires/1 and holds/1 never see the rule.\r\nkb_issue(error, no_level, Id) :-\r\n    rule_id(Id),\r\n    \\+ rule_level(Id, _).\r\nkb_issue(error, bad_level, Id-L) :-\r\n    rule_level(Id, L),\r\n    \\+ member(L, [1, 2, 3]).\r\nkb_issue(warning, orphan_level, Id) :-\r\n    rule_level(Id, _),\r\n    \\+ rule_id(Id).\r\n\r\nkb_issue(error, no_text, Id) :-\r\n    rule_id(Id),\r\n    \\+ rule_text(Id, _).\r\nkb_issue(warning, orphan_text, Id) :-\r\n    rule_text(Id, _),\r\n    \\+ rule_id(Id).\r\n\r\n% A concern with nothing the user can do about it.\r\nkb_issue(warning, no_action, Id) :-\r\n    rule_clause(Id, _, CF, _),\r\n    number(CF),\r\n    CF < 0,\r\n    \\+ next_action(Id, _).\r\nkb_issue(warning, orphan_action, Id) :-\r\n    next_action(Id, _),\r\n    \\+ rule_id(Id).\r\n\r\n% boss_infer.pl names these rules directly.\r\nreserved_rule(r10, override).  reserved_rule(r11, override).\r\nreserved_rule(r21, override).  reserved_rule(r22, ladder).\r\nreserved_rule(r23, ladder).    reserved_rule(r24, ladder).\r\nreserved_rule(r25, ladder).\r\n\r\nkb_issue(error, reserved_missing, Id) :-\r\n    reserved_rule(Id, _),\r\n    \\+ rule_id(Id).\r\n\r\n% ------------------------------------------------------------\r\n% 3. Vocabulary: rules speak only about what the system knows\r\n% ------------------------------------------------------------\r\n\r\nkb_issue(error, undefined_goal, Id-(N/A)) :-\r\n    rule_clause(Id, _, _, Body),\r\n    body_goal(Body, G),\r\n    callable(G),\r\n    functor(G, N, A),\r\n    \\+ builtin(N/A),\r\n    \\+ current_predicate(N/A).\r\n\r\n% A value no answer can ever produce: the condition can never hold.\r\nkb_issue(error, unknown_value, Id-T) :-\r\n    rule_clause(Id, _, _, Body),\r\n    tested_value(Body, A, V),\r\n    has_domain(A),\r\n    \\+ known_attr_value(A, V),\r\n    T =.. [A, V].\r\n\r\n% The questionnaire offers an answer the knowledge base would reject\r\n% as unrecognised (boss_derive.pl), e.g. after a fixed fact is removed.\r\nkb_issue(error, ui_unrecognised, T) :-\r\n    ui_value(A, V),\r\n    T =.. [A, V],\r\n    checked_input(T),\r\n    \\+ known_value(T).\r\n\r\nkb_issue(error, unknown_verdict, Id-V) :-\r\n    concludes_term(Id, recommendation(V)),\r\n    \\+ verdict_text(V, _).\r\n\r\nkb_issue(warning, gap_unlabelled, Id-G) :-\r\n    concludes_term(Id, validation_gap(G)),\r\n    \\+ gap_label(G, _).\r\n\r\n% The body asks for a conclusion that no rule draws.\r\nkb_issue(warning, unsupported_holds, Id-C) :-\r\n    rule_clause(Id, _, _, Body),\r\n    body_goal(Body, G),\r\n    ( G = holds(C) ; G = holds_upto(_, C) ),\r\n    nonvar(C),\r\n    \\+ concludes_term(_, C).\r\n\r\n% ------------------------------------------------------------\r\n% 4. Stratification (boss_infer.pl header)\r\n% A rule may only read conclusions from a level below its own,\r\n% otherwise holds/1 can re-enter the rule it is proving.\r\n% ------------------------------------------------------------\r\n\r\nreads_level(holds(_), 2).\r\nreads_level(holds_upto(K, _), K).\r\nreads_level(core_positive, 2).\r\nreads_level(weakness(_), 2).\r\nreads_level(weakness_count(_), 2).\r\nreads_level(severe_risk(_), 2).\r\nreads_level(severe_risk_count(_), 2).\r\nreads_level(absolute_override, 3).\r\nreads_level(fires(_), 3).\r\n\r\nkb_issue(error, stratification, Id-G) :-\r\n    rule_clause(Id, _, _, Body),\r\n    rule_level(Id, L),\r\n    L < 3,\r\n    body_goal(Body, G),\r\n    reads_level(G, K),\r\n    ( var(K) ; K >= L ).\r\n\r\n% Level 3 is outside holds/1: a non-verdict drawn there is never read.\r\nkb_issue(warning, level_unread, Id-C) :-\r\n    rule_level(Id, 3),\r\n    concludes_term(Id, C),\r\n    C \\= recommendation(_).\r\nkb_issue(warning, verdict_below_3, Id) :-\r\n    rule_level(Id, L),\r\n    L < 3,\r\n    concludes_term(Id, recommendation(_)).\r\n\r\n% The SRS 9.1 ladder consults R10, R11, R21 and R23-R25 by name. A new\r\n% verdict rule is traced and explained, but cannot change the verdict.\r\nkb_issue(warning, not_in_ladder, Id) :-\r\n    rule_level(Id, 3),\r\n    rule_id(Id),\r\n    \\+ reserved_rule(Id, _).\r\n\r\n% ------------------------------------------------------------\r\n% 5. Consistency: two rules that can fire together and disagree\r\n% ------------------------------------------------------------\r\n\r\n% Attributes that legitimately collect several values at once, and\r\n% the verdict, whose conflicts the SRS 9.1 ladder resolves.\r\nmulti_valued(validation_gap).\r\nmulti_valued(red_flag).\r\nmulti_valued(recommendation).\r\n\r\n% No categorical condition tells the two rules apart. Numeric tests\r\n% are not compared, so this is a warning, not a proof.\r\nexclusive(B1, B2) :-\r\n    constraint(B1, A, V1s),\r\n    constraint(B2, A, V2s),\r\n    \\+ ( member(V, V1s), member(V, V2s) ).\r\n\r\nkb_issue(warning, conflict, (I1-I2):C1/C2) :-\r\n    rule_clause(I1, _, _, B1),\r\n    rule_clause(I2, _, _, B2),\r\n    I1 @< I2,\r\n    rule_level(I1, L), rule_level(I2, L),\r\n    concludes_term(I1, C1),\r\n    concludes_term(I2, C2),\r\n    C1 =.. [F, V1],\r\n    C2 =.. [F, V2],\r\n    \\+ multi_valued(F),\r\n    V1 \\== V2,\r\n    \\+ exclusive(B1, B2).\r\n\r\n% ------------------------------------------------------------\r\n% Plain-language reading of each check, for the editor.\r\n% ------------------------------------------------------------\r\n\r\ncheck_text(cf_not_number,     'Certainty factor is not a number').\r\ncheck_text(cf_out_of_range,   'Certainty factor is outside -1 .. 1').\r\ncheck_text(id_not_atom,       'Rule id must be an atom such as r26').\r\ncheck_text(duplicate_id,      'Two rules share this id').\r\ncheck_text(no_level,          'No rule_level/2, so the rule can never fire').\r\ncheck_text(bad_level,         'Rule level must be 1, 2 or 3').\r\ncheck_text(orphan_level,      'rule_level/2 for a rule that does not exist').\r\ncheck_text(no_text,           'No rule_text/2, so the rule cannot be explained').\r\ncheck_text(orphan_text,       'rule_text/2 for a rule that does not exist').\r\ncheck_text(no_action,         'A concern with no next_action/2 for the user').\r\ncheck_text(orphan_action,     'next_action/2 for a rule that does not exist').\r\ncheck_text(reserved_missing,  'boss_infer.pl names this rule directly; it must exist').\r\ncheck_text(undefined_goal,    'The body calls a predicate the knowledge base does not define').\r\ncheck_text(unknown_value,     'A value no answer can produce, so the condition never holds').\r\ncheck_text(ui_unrecognised,   'The questionnaire offers this answer, but the knowledge base no longer recognises it').\r\ncheck_text(unknown_verdict,   'A verdict with no verdict_text/2').\r\ncheck_text(gap_unlabelled,    'A validation gap with no gap_label/2').\r\ncheck_text(unsupported_holds, 'Reads a conclusion that no rule draws').\r\ncheck_text(stratification,    'Reads conclusions from its own level or above (can loop)').\r\ncheck_text(level_unread,      'Level 3 is invisible to holds/1, so nothing can use this conclusion').\r\ncheck_text(verdict_below_3,   'A verdict drawn below level 3 is not a recommendation rule').\r\ncheck_text(not_in_ladder,     'The SRS 9.1 ladder does not consult this rule; it cannot change the verdict').\r\ncheck_text(conflict,          'Can fire together with a different conclusion (numeric tests not compared)').\r\n"};
